svg.script:
(function () {
  var names = ["index.html", "Why.html", "whyrevived.html"];
  var frame = document.getElementById("app");
  var base = new URL("./", location.href).href;
  function show(html) {
    var head = html.match(/<head\b[^>]*>/i);
    if (head && !/<base\b/i.test(html.slice(0, head.index + head[0].length + 400))) {
      html = html.replace(head[0], head[0] + '<base href="' + base.replace(/"/g, "%22") + '">');
    }
    // jsDelivr sends the HTML file as text/plain, so an iframe pointed at
    // that URL shows the source. A text/html blob renders the same bytes.
    var blob = new Blob([html], { type: "text/html;charset=utf-8" });
    frame.src = URL.createObjectURL(blob);
  }
  function next(i) {
    if (!frame || i >= names.length) return;
    fetch(names[i]).then(function (res) {
      if (!res.ok) { next(i + 1); return; }
      return res.text().then(show);
    }, function () { next(i + 1); });
  }
  next(0);
})();
